 setRole(beta.data.role);
 const results=await Promise.all([db.from('profiles').select('*'),db.from('services').select('*').order('created_at',{ascending:false}),db.from('orders').select('*').order('created_at',{ascending:false}),db.from('portfolio_items').select('*').order('created_at',{ascending:false}),db.from('referrals').select('*').order('created_at',{ascending:false}),db.from('business_rules').select('*').single(),db.from('partner_codes').select('code').eq('partner_id',user.id).maybeSingle()]);
