async function resendConfirmation(){if(busy||emailCooldown>0)return;setBusy(true);setError('');setNotice('');try{if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))throw new Error(t('Эхлээд имэйл хаягаа оруулна уу.','Enter your email address first.'));const db=await marketplaceClient();const r=await db.auth.resend({type:'signup',email:email.trim().toLowerCase(),options:{emailRedirectTo:location.origin+'/login/'}});if(r.error)throw r.error;setEmailCooldown(60);setNotice(t('Баталгаажуулах имэйл хүсэлт илгээгдлээ. Inbox болон Spam хавтсаа шалгана уу. Холбоосыг нээсний дараа энэ хуудсанд буцаж нэвтэрнэ үү.','Confirmation requested. Check Inbox and Spam. Open the link, then return here to sign in.'));}catch(e){fail(e)}finally{setBusy(false)}}
async function refreshMessages(){if(!uid||!role)return;const db=await marketplaceClient();const r=await db.from('messages').select('id,sender_id,recipient_id,body,created_at').or('sender_id.eq.'+uid+',recipient_id.eq.'+uid).order('created_at',{ascending:true}).limit(500);if(r.error)throw r.error;setMessages(r.data as ChatMessage[])}
useEffect(()=>{
  if(!uid||!role||tab!=='messages')return;
  let active=true;
  let unsubscribe=()=>{};
  setRealtimeStatus('connecting');
  const sync=async()=>{
    const db=await marketplaceClient();
    const response=await db.from('messages')
      .select('id,sender_id,recipient_id,body,created_at')
      .or('sender_id.eq.'+uid+',recipient_id.eq.'+uid)
      .order('created_at',{ascending:true}).limit(500);
    if(!active||response.error)return;
    // Merge rather than overwrite events arriving while a fetch is in flight.
    setMessages(existing=>{
      const own=existing.filter(message=>message.sender_id===uid||message.recipient_id===uid);
      return (response.data as ChatMessage[]).reduce(appendUniqueMessage,own);
    });
  };
  void marketplaceClient().then(db=>{
    if(!active)return;
    const accept=(payload:{new:Record<string,unknown>})=>{
      const message=payload.new as ChatMessage;
      if(!active||!message.id||!(message.sender_id===uid||message.recipient_id===uid))return;
      setMessages(list=>appendUniqueMessage(list,message));
    };
    const channel=db.channel('hustle-beta-inbox-'+uid)
      .on('postgres_changes',{event:'INSERT',schema:'public',table:'messages',filter:'recipient_id=eq.'+uid},accept)
      .on('postgres_changes',{event:'INSERT',schema:'public',table:'messages',filter:'sender_id=eq.'+uid},accept)
      .subscribe(status=>{
        if(!active)return;
        if(status==='SUBSCRIBED'){setRealtimeStatus('connected');void sync();}
        if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'||status==='CLOSED')setRealtimeStatus('fallback');
      });
    unsubscribe=()=>{void db.removeChannel(channel)};
    void sync();
  }).catch(()=>{if(active)setRealtimeStatus('fallback')});
  // Missed network events and inactive tabs still converge on the DB.
  const interval=window.setInterval(()=>{if(active)void sync()},30000);
  return()=>{active=false;clearInterval(interval);unsubscribe()};
},[uid,role,tab]);
