async function upload(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const f=new FormData(form),file=f.get('image') as File;await perform(async()=>{if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw new Error(t('JPEG, PNG, WebP зураг, дээд хэмжээ 5 MB.','Use JPEG, PNG or WebP, maximum 5 MB.'));const db=await marketplaceClient(),path=uid+'/'+crypto.randomUUID()+'.'+({ 'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type]);const u=await db.storage.from('portfolio').upload(path,file,{contentType:file.type});if(u.error)throw u.error;const r=await db.from('portfolio_items').insert({seller_id:uid,title:f.get('title'),object_path:path});if(r.error){await db.storage.from('portfolio').remove([path]);throw r.error}form.reset()},t('Portfolio зураг хадгалагдлаа.','Portfolio image uploaded.'))}
